function fieldComparison(records,raw=false){
  const keys=raw?[...new Set(records.flatMap(r=>Object.keys(r.raw||{})))].sort():semanticFields.filter(key=>records.some(r=>Object.hasOwn(r,key)));
  return keys.map(key=>{
